@startuml

class User {
  + fullName : string
}

class UnderAgedUser extends User {
  + studentCard : string
}

class AdultUser extends User {
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowingHistory {
  + borrowDate : date
  + returnDate : date
}

User "1" -- "*" BorrowingHistory : has
User "1" -- "0..4" Book : borrows
BorrowingHistory "*" -- "1" Book : includes

@enduml

